package solution

import "testing"

func TestSolve(t *testing.T) {
	cases := []struct {
		name    string
		in      []int
		want    int
		wantErr bool
	}{
		{"all positive", []int{1, 2, 3}, 6, false},
		{"empty", []int{}, 0, false},
		{"has negative", []int{1, -2, 3}, 0, true},
	}
	for _, c := range cases {
		got, err := Solve(c.in)
		if (err != nil) != c.wantErr {
			t.Errorf("%s: err=%v wantErr=%v", c.name, err, c.wantErr)
		}
		if !c.wantErr && got != c.want {
			t.Errorf("%s: Solve=%d want %d", c.name, got, c.want)
		}
	}
}

